<?php declare(strict_types=1); session_start(); require_once '/var/www/compte/config/database.php'; require_once '/var/www/compte/config/services.php'; /* |-------------------------------------------------------------------------- | Authentification |-------------------------------------------------------------------------- */ if (!isset($_SESSION['utilisateur_id'])) { http_response_code(401); exit('Vous devez être connecté.'); } /* |-------------------------------------------------------------------------- | Vérification des droits |-------------------------------------------------------------------------- */ try { $autorise = utilisateurAAccesService( $pdo, (int) $_SESSION['utilisateur_id'], 'video' ); } catch (Throwable $exception) { error_log( 'Erreur droits téléchargement vidéo : ' . $exception->getMessage() ); http_response_code(500); exit('Erreur lors de la vérification des autorisations.'); } if (!$autorise) { http_response_code(403); exit('Accès non autorisé.'); } /* |-------------------------------------------------------------------------- | Répertoire vidéo |-------------------------------------------------------------------------- */ $repertoireVideos = '/mnt/video'; /* |-------------------------------------------------------------------------- | Récupération du nom du fichier |-------------------------------------------------------------------------- */ $nomFichier = $_GET['f'] ?? ''; if ( !is_string($nomFichier) || $nomFichier === '' || basename($nomFichier) !== $nomFichier || str_contains($nomFichier, "\0") ) { http_response_code(400); exit('Nom de fichier invalide.'); } /* |-------------------------------------------------------------------------- | Vérification de l'extension |-------------------------------------------------------------------------- */ $extensionsAutorisees = [ 'mp4', 'webm', 'ogg', ]; $extension = strtolower( pathinfo($nomFichier, PATHINFO_EXTENSION) ); if (!in_array($extension, $extensionsAutorisees, true)) { http_response_code(403); exit('Type de fichier non autorisé.'); } /* |-------------------------------------------------------------------------- | Vérification du fichier |-------------------------------------------------------------------------- */ $chemin = $repertoireVideos . '/' . $nomFichier; if ( !is_file($chemin) || !is_readable($chemin) ) { http_response_code(404); exit('Vidéo introuvable.'); } $taille = filesize($chemin); if ($taille === false) { http_response_code(500); exit('Impossible de lire le fichier.'); } /* |-------------------------------------------------------------------------- | Préparation du téléchargement |-------------------------------------------------------------------------- */ while (ob_get_level() > 0) { ob_end_clean(); } header('Content-Type: application/octet-stream'); header( 'Content-Disposition: attachment; filename="' . addcslashes($nomFichier, "\\\"") . '"; filename*=UTF-8\'\'' . rawurlencode($nomFichier) ); header('Content-Length: ' . $taille); header('Cache-Control: private, no-store'); header('X-Content-Type-Options: nosniff'); /* |-------------------------------------------------------------------------- | Envoi du fichier |-------------------------------------------------------------------------- */ $handle = fopen($chemin, 'rb'); if ($handle === false) { http_response_code(500); exit('Impossible d' . "'" . 'ouvrir la vidéo.'); } fpassthru($handle); fclose($handle); exit;
